mapper.select:
SELECT quantity
  FROM t_stock
 WHERE product_id = #{productId}
   AND warehouse_id = #{warehouseId}
   FOR UPDATE

mapper.update:
UPDATE t_stock
   SET quantity = quantity + #{delta},
       updated_at = #{now},
       updated_by = 0
 WHERE product_id = #{productId}
   AND warehouse_id = #{warehouseId}
